<div class="admin-title"><div><p class="eyebrow">Inbox</p><h1>Contact inquiries</h1></div></div><div class="inquiry-list"><?php foreach($items as $i):?><article class="panel"><div><span class="badge"><?=e($i['status'])?></span><h2><?=e($i['subject'])?></h2><p><b><?=e($i['full_name'])?></b> · <a href="mailto:<?=e($i['email'])?>"><?=e($i['email'])?></a> · <?=e($i['company'])?></p><p><?=nl2br(e($i['message']))?></p><small>Received <?=e($i['created_at'])?> · Service: <?=e($i['service'])?></small></div><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$i['id']?>"><label>Status<select name="status"><?php foreach(['new','in_progress','resolved','spam'] as $s):?><option <?=$i['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><button class="button small">Update</button></form></article><?php endforeach;?><?php if(!$items):?><div class="panel empty">No inquiries received yet.</div><?php endif;?></div>
